{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "\u7f16\u53f7\u6620\u5c04\u8865\u4e01",
    "description": "\u6a21\u578b\u53ea\u63d0\u4ea4\u7a33\u5b9a\u6620\u5c04\u952e\u3001\u7c7b\u522b\u3001\u5206\u6790\u5f15\u7528\u548c\u53ef\u9009\u65e2\u6709\u7f16\u53f7\uff1b\u62d2\u7edd\u6b63\u6587\u3001\u6458\u8981\u3001\u8ba1\u6570\u5668\u53ca\u672a\u77e5\u5b57\u6bb5\uff0c\u811a\u672c\u8d1f\u8d23\u5b9e\u9645\u5206\u914d\u3002",
    "type": "object",
    "additionalProperties": false,
    "required": [
        "patch_version",
        "requirement_id",
        "base_prd_version",
        "base_analysis_revision",
        "items"
    ],
    "properties": {
        "patch_version": {
            "const": "1.0"
        },
        "requirement_id": {
            "type": "string",
            "pattern": "^[^\\s/]+$"
        },
        "base_prd_version": {
            "anyOf": [
                {
                    "type": "null"
                },
                {
                    "type": "string",
                    "pattern": "^(?:0\\.[1-9][0-9]*|[1-9][0-9]*\\.(?:0|[1-9][0-9]*)(?:-draft)?)$"
                }
            ]
        },
        "base_analysis_revision": {
            "type": "integer",
            "minimum": 1
        },
        "items": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                    "mapping_key",
                    "kind",
                    "analysis_refs"
                ],
                "properties": {
                    "mapping_key": {
                        "type": "string",
                        "minLength": 1,
                        "pattern": "\\S"
                    },
                    "kind": {
                        "enum": [
                            "goal",
                            "scenario",
                            "functional_requirement",
                            "business_rule",
                            "constraint",
                            "non_functional_requirement",
                            "acceptance_criterion",
                            "flow",
                            "state",
                            "boundary",
                            "exception"
                        ]
                    },
                    "analysis_refs": {
                        "type": "array",
                        "items": {
                            "type": "string",
                            "pattern": "^[^\\s/]+/(?:GOAL|SCN|FR|BR|CON|NFR|AC|FLOW|STATE|BND|EXC|GAP|CNF|Q|ASM|DEC)-[1-9][0-9]*$"
                        },
                        "uniqueItems": true,
                        "minItems": 1
                    },
                    "prd_id": {
                        "type": "string",
                        "pattern": "^PRD-(?:GOAL|SCN|FR|BR|CON|NFR|AC|FLOW|STATE|BND|EXC)-(?=\\d{3,}$)0*[1-9][0-9]*$"
                    }
                }
            }
        }
    }
}
{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "\u7f3a\u53e3\u56de\u4ea4\u6587\u4ef6",
    "description": "\u5b9a\u4e49\u7248\u672c\u5316\u7f3a\u53e3\u5c01\u88c5\u53ca\u5173\u95ed\u4f9d\u636e\uff1b\u5141\u8bb8\u6269\u5c55\uff0c\u5206\u6790\u4fa7\u53ea\u80fd\u5728\u63a5\u6536\u4fdd\u5b58\u6210\u529f\u540e\u6807\u8bb0\u5bf9\u5e94\u72b6\u6001\u3002",
    "type": "object",
    "required": [
        "schema_version",
        "requirement_id",
        "counters",
        "requests"
    ],
    "properties": {
        "schema_version": {
            "const": "1.0"
        },
        "requirement_id": {
            "type": "string",
            "pattern": "^[^\\s/]+$"
        },
        "counters": {
            "type": "object",
            "required": [
                "GAPREQ"
            ],
            "properties": {
                "GAPREQ": {
                    "type": "integer",
                    "minimum": 0
                }
            }
        },
        "requests": {
            "type": "array",
            "items": {
                "$ref": "#/$defs/request"
            }
        }
    },
    "$defs": {
        "request": {
            "type": "object",
            "required": [
                "id",
                "needed_for",
                "description",
                "related_analysis_refs",
                "raised_in",
                "status"
            ],
            "properties": {
                "id": {
                    "type": "string",
                    "pattern": "^GAPREQ-[1-9][0-9]*$"
                },
                "needed_for": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "\\S"
                },
                "description": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "\\S"
                },
                "related_analysis_refs": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "pattern": "^[^\\s/]+/(?:GOAL|SCN|FR|BR|CON|NFR|AC|FLOW|STATE|BND|EXC|GAP|CNF|Q|ASM|DEC)-[1-9][0-9]*$"
                    },
                    "uniqueItems": true
                },
                "raised_in": {
                    "type": "string",
                    "pattern": "^(?:0\\.[1-9][0-9]*|[1-9][0-9]*\\.(?:0|[1-9][0-9]*)(?:-draft)?)$"
                },
                "status": {
                    "enum": [
                        "open",
                        "handed_over",
                        "closed"
                    ]
                },
                "resolution": {
                    "type": "object",
                    "required": [
                        "kind",
                        "analysis_refs",
                        "reason"
                    ],
                    "properties": {
                        "kind": {
                            "enum": [
                                "supplied",
                                "not_needed"
                            ]
                        },
                        "analysis_refs": {
                            "type": "array",
                            "items": {
                                "type": "string",
                                "pattern": "^[^\\s/]+/(?:GOAL|SCN|FR|BR|CON|NFR|AC|FLOW|STATE|BND|EXC|GAP|CNF|Q|ASM|DEC)-[1-9][0-9]*$"
                            },
                            "uniqueItems": true,
                            "minItems": 1
                        },
                        "reason": {
                            "type": "string",
                            "minLength": 1,
                            "pattern": "\\S"
                        }
                    }
                }
            },
            "allOf": [
                {
                    "if": {
                        "properties": {
                            "status": {
                                "const": "closed"
                            }
                        },
                        "required": [
                            "status"
                        ]
                    },
                    "then": {
                        "required": [
                            "resolution"
                        ]
                    }
                }
            ]
        }
    }
}

